CREATE TYPE "MediaType" AS ENUM ('IMAGE', 'VIDEO');
CREATE TYPE "QueueStatus" AS ENUM ('PENDING', 'DISPLAYING', 'COMPLETED', 'EXPIRED');
CREATE TYPE "EventSource" AS ENUM ('TURNSTILE', 'NEXTFIT', 'ADMIN', 'OTHER');
CREATE TYPE "DeviceStatus" AS ENUM ('ONLINE', 'OFFLINE');

CREATE TABLE "AdminUser" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "AdminUser_email_key" ON "AdminUser"("email");
CREATE TABLE "SponsorMedia" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "fileUrl" TEXT NOT NULL, "type" "MediaType" NOT NULL, "mimeType" TEXT NOT NULL, "durationSec" INTEGER NOT NULL DEFAULT 10, "sortOrder" INTEGER NOT NULL DEFAULT 0, "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "active" BOOLEAN NOT NULL DEFAULT true, "priority" INTEGER NOT NULL DEFAULT 0, "sponsorName" TEXT, "sponsorLink" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "SponsorMedia_active_sortOrder_idx" ON "SponsorMedia"("active", "sortOrder");
CREATE TABLE "Student" ("id" TEXT PRIMARY KEY, "externalId" TEXT, "name" TEXT NOT NULL, "photoUrl" TEXT, "birthDate" TIMESTAMP(3), "active" BOOLEAN NOT NULL DEFAULT true, "source" "EventSource" NOT NULL DEFAULT 'OTHER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Student_externalId_key" ON "Student"("externalId");
CREATE TABLE "Birthday" ("id" TEXT PRIMARY KEY, "studentId" TEXT, "name" TEXT NOT NULL, "birthDate" TIMESTAMP(3) NOT NULL, "photoUrl" TEXT, "message" TEXT, "showLastName" BOOLEAN NOT NULL DEFAULT false, "active" BOOLEAN NOT NULL DEFAULT true, "externalSource" TEXT, "externalId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Birthday_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Birthday_active_birthDate_idx" ON "Birthday"("active", "birthDate");
CREATE TABLE "EntryEvent" ("id" TEXT PRIMARY KEY, "studentId" TEXT, "externalId" TEXT NOT NULL, "studentName" TEXT NOT NULL, "enteredAt" TIMESTAMP(3) NOT NULL, "unitId" TEXT NOT NULL, "source" "EventSource" NOT NULL DEFAULT 'TURNSTILE', "duplicate" BOOLEAN NOT NULL DEFAULT false, "rawPayload" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EntryEvent_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "EntryEvent_externalId_enteredAt_idx" ON "EntryEvent"("externalId", "enteredAt");
CREATE TABLE "WelcomeQueue" ("id" TEXT PRIMARY KEY, "entryEventId" TEXT NOT NULL, "displayName" TEXT NOT NULL, "message" TEXT NOT NULL, "status" "QueueStatus" NOT NULL DEFAULT 'PENDING', "priority" INTEGER NOT NULL DEFAULT 0, "expiresAt" TIMESTAMP(3) NOT NULL, "displayedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "WelcomeQueue_entryEventId_fkey" FOREIGN KEY ("entryEventId") REFERENCES "EntryEvent"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "WelcomeQueue_entryEventId_key" ON "WelcomeQueue"("entryEventId");
CREATE INDEX "WelcomeQueue_status_createdAt_idx" ON "WelcomeQueue"("status", "createdAt");
CREATE TABLE "DisplayDevice" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "unitId" TEXT NOT NULL, "tokenHash" TEXT, "status" "DeviceStatus" NOT NULL DEFAULT 'OFFLINE', "lastSeenAt" TIMESTAMP(3), "currentMedia" TEXT, "paused" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "DisplayDevice_name_key" ON "DisplayDevice"("name");
CREATE TABLE "DisplayConnection" ("id" TEXT PRIMARY KEY, "deviceId" TEXT NOT NULL, "connectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "disconnectedAt" TIMESTAMP(3), "ipAddress" TEXT, "userAgent" TEXT, CONSTRAINT "DisplayConnection_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "DisplayDevice"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "SystemSettings" ("id" TEXT PRIMARY KEY DEFAULT 'default', "welcomeDurationSec" INTEGER NOT NULL DEFAULT 15, "birthdayDurationSec" INTEGER NOT NULL DEFAULT 8, "duplicateWindowMin" INTEGER NOT NULL DEFAULT 10, "defaultWelcomeMessage" TEXT NOT NULL DEFAULT 'Seja bem-vindo, {nome}!', "alternateMessages" JSONB NOT NULL DEFAULT '[]', "randomMessages" BOOLEAN NOT NULL DEFAULT false, "logoUrl" TEXT NOT NULL DEFAULT '/demo/logo-ct.svg', "fallbackTitle" TEXT NOT NULL DEFAULT 'CT Ítalo Vieira', "fallbackSubtitle" TEXT NOT NULL DEFAULT 'Força. Movimento. Evolução.', "tvTokenHash" TEXT, "entryApiKeyHash" TEXT, "timezone" TEXT NOT NULL DEFAULT 'America/Sao_Paulo', "unitId" TEXT NOT NULL DEFAULT 'ct-italo-vieira', "showClock" BOOLEAN NOT NULL DEFAULT true, "maxQueueSize" INTEGER NOT NULL DEFAULT 50, "eventTtlMin" INTEGER NOT NULL DEFAULT 30, "reducedDurationThreshold" INTEGER NOT NULL DEFAULT 8, "reducedDurationSec" INTEGER NOT NULL DEFAULT 8, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "adminUserId" TEXT, "action" TEXT NOT NULL, "entity" TEXT NOT NULL, "entityId" TEXT, "details" JSONB, "ipAddress" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_adminUserId_fkey" FOREIGN KEY ("adminUserId") REFERENCES "AdminUser"("id") ON DELETE SET NULL ON UPDATE CASCADE);
